<?php $order=$data['order'];$address=json_decode((string)$order['shipping_address_snapshot'],true)?:[]; ?><section class="page-intro shell"><span class="eyebrow">ORDER <?= e($order['order_number']) ?></span><h1>অর্ডারের অগ্রগতি~।</h1><p>অবস্থা: <strong><?= e($order['status']) ?></strong> · Payment: cash on delivery</p></section><section class="section shell"><div class="table-wrap"><table><thead><tr><th>পণ্য</th><th>পরিমাণ</th><th>একক দাম</th><th>মোট</th></tr></thead><tbody><?php foreach($order['items'] as $item): ?><tr><td><?= e($item['product_name']) ?><?php if($order['status']==='delivered'&&!empty($item['product_id'])): ?><details class="review-editor"><summary>রিভিউ লিখুন</summary><form class="form-card" action="/account/reviews" method="post"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= e($item['product_id']) ?>"><input type="hidden" name="return_to" value="<?= e('/account/orders/'.$order['id']) ?>"><label>Rating</label><select name="rating" required><?php for($rating=5;$rating>=1;$rating--): ?><option value="<?= $rating ?>"><?= $rating ?> / 5</option><?php endfor; ?></select><label>Title (ঐচ্ছিক)</label><input name="title" maxlength="160"><label>আপনার মতামত</label><textarea name="body" maxlength="10000" rows="3"></textarea><button class="button button-green" type="submit">রিভিউ জমা দিন</button></form></details><?php endif; ?></td><td><?= (int)$item['quantity'] ?></td><td><?= e(format_price((float)$item['unit_price'],$order['currency'])) ?></td><td><?= e(format_price((float)$item['line_total'],$order['currency'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!empty($order['shipment'])): ?><section class="panel shipment-card"><h2>ডেলিভারি ট্র্যাকিং</h2><p><?= e($order['shipment']['carrier']??'') ?> <?= e($order['shipment']['tracking_number']??'') ?><br>Shipment: <?= e($order['shipment']['status']) ?></p><?php if(!empty($order['shipment']['tracking_url'])): ?><a class="text-link" href="<?= e($order['shipment']['tracking_url']) ?>" rel="nofollow noopener">কুরিয়ার সাইটে ট্র্যাক করুন →</a><?php endif; ?></section><?php endif; ?><div class="order-summary-grid"><section class="panel"><h2>অর্ডারের হিসাব</h2><p>Subtotal: <?= e(format_price((float)$order['subtotal'],$order['currency'])) ?></p><p>Discount: <?= e(format_price((float)$order['discount_total'],$order['currency'])) ?></p><p>Shipping: <?= e(format_price((float)$order['shipping_total'],$order['currency'])) ?></p><p>Tax: <?= e(format_price((float)$order['tax_total'],$order['currency'])) ?></p><strong>Total: <?= e(format_price((float)$order['grand_total'],$order['currency'])) ?></strong></section><section class="panel"><h2>ডেলিভারি ঠিকানা</h2><p><?= e($address['recipient_name']??'') ?><br><?= e($address['phone']??'') ?><br><?= e($address['line1']??'') ?> <?= e($address['line2']??'') ?><br><?= e($address['locality']??'') ?> <?= e($address['region']??'') ?> <?= e($address['postal_code']??'') ?></p></section></div><section class="account-section"><h2>স্ট্যাটাস ইতিহাস</h2><ol class="timeline"><?php foreach($order['history'] as $event): ?><li><strong><?= e($event['status']) ?></strong><span><?= e($event['note']??'') ?></span><time><?= e(date('d M Y H:i',strtotime($event['created_at']))) ?></time></li><?php endforeach; ?></ol></section><?php if(in_array($order['status'],['delivered','confirmed','processing','shipped'],true)): ?><form class="form-card" action="/account/returns" method="post"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= e($order['id']) ?>"><h2>Return / exchange অনুরোধ</h2><label for="type">অনুরোধের ধরন</label><select id="type" name="type"><option value="return">Return</option><option value="exchange">Exchange</option><option value="refund">Refund review</option></select><label for="reason">কারণ</label><textarea id="reason" name="reason" rows="4" minlength="5" maxlength="2000" required></textarea><button class="button button-green" type="submit">অনুরোধ জমা দিন</button></form><?php endif; ?></section>
